<template><ion-page><ion-header><ion-toolbar><ion-title>Profile</ion-title></ion-toolbar></ion-header><ion-content><main class="page-shell"><section class="profile"><div class="avatar">JC</div><div><h1>John Clark Culla</h1><p>Movie enthusiast</p></div></section><section class="stats"><div><strong>{{ movies.length }}</strong><span>Total movies</span></div><div><strong>{{ watchedMovies.length }}</strong><span>Watched</span></div><div><strong>{{ favoriteMovies.length }}</strong><span>Favorites</span></div><div><strong>{{ averageRating }}</strong><span>Avg. rating</span></div></section><section class="progress-section"><h2>Your progress</h2><div class="progress-label"><span>Movies watched</span><strong>{{ progress }}%</strong></div><ion-progress-bar :value="progress / 100" /><div class="progress-label"><span>Watchlist complete</span><strong>{{ watchlistProgress }}%</strong></div><ion-progress-bar color="secondary" :value="watchlistProgress / 100" /></section><section><h2>Favorite genres</h2><div class="genre-list"><ion-chip v-for="genre in favoriteGenres" :key="genre" color="primary">{{ genre }}</ion-chip></div></section></main></ion-content></ion-page></template>
<script setup lang="ts">import { computed } from 'vue'; import { IonChip, IonContent, IonHeader, IonPage, IonProgressBar, IonTitle, IonToolbar } from '@ionic/vue'; import { useMovieStore } from '../../stores/movieStore'; const { movies, watchedMovies, watchlistMovies, favoriteMovies } = useMovieStore(); const averageRating = computed(() => movies.value.length ? (movies.value.reduce((sum, movie) => sum + movie.rating, 0) / movies.value.length).toFixed(1) : '0.0'); const progress = computed(() => movies.value.length ? Math.round(watchedMovies.value.length / movies.value.length * 100) : 0); const watchlistProgress = computed(() => movies.value.length ? Math.round(watchlistMovies.value.length / movies.value.length * 100) : 0); const favoriteGenres = computed(() => [...new Set(favoriteMovies.value.map((movie) => movie.genre))]);</script>
<style scoped>.page-shell { max-width: 760px; margin: auto; padding: 24px 16px; }.profile { display: flex; align-items: center; gap: 16px; margin-bottom: 28px; }.avatar { width: 66px; height: 66px; display: grid; place-items: center; border-radius: 50%; background: linear-gradient(135deg, #ec4968, #7139d2); font-size: 1.3rem; font-weight: 800; }.profile h1 { margin: 0; }.profile p { color: var(--ion-color-medium); margin: 5px 0; }.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; background: var(--surface-card); border: 1px solid var(--surface-border); padding: 18px 8px; border-radius: 16px; text-align: center; }.stats strong, .stats span { display: block; }.stats strong { font-size: 1.4rem; }.stats span { color: var(--ion-color-medium); font-size: .68rem; margin-top: 4px; }.progress-section { margin: 32px 0; }.progress-label { display: flex; justify-content: space-between; margin: 18px 0 7px; font-size: .85rem; }.genre-list { display: flex; flex-wrap: wrap; gap: 4px; }</style>
